const D = { energy: .62, density: .55, speed: 1, scale: 1, well: .5, scatter: .5, momentum: .5, hue: 200, x: .5, y: .5, style: 'phase-density', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W = width, H = height, TAU = 6.28318530718;
const clp = (v,a,b)=> v<a?a:v>b?b:v;

// --- coarse complex-field grid (<=140), aspect-matched, size-keyed cache ---
let GW, GH;
if (W >= H) { GW = 132; GH = Math.max(8, Math.round(132 * H / W)); }
else        { GH = 132; GW = Math.max(8, Math.round(132 * W / H)); }
GW = Math.min(140, GW); GH = Math.min(140, GH);
const GN = GW * GH;

if (!S.re || S.gw !== GW || S.gh !== GH) {
  if (S.buf && S.buf.remove) S.buf.remove();
  S.buf = createGraphics(GW, GH); S.buf.pixelDensity(1);
  S.re = new Float32Array(GN); S.im = new Float32Array(GN); S.pb = new Float32Array(GN);
  S.gw = GW; S.gh = GH; S.expo = 0.2; S.seedUsed = null;
}

// --- inline seed hash (no p5 random) ---
const fr = i => { const s = Math.sin(i * 127.1 + (P.seed|0) * 311.7) * 43758.5453; return s - Math.floor(s); };

// --- (re)inject a gaussian x plane-wave packet, then renormalise total prob ---
function injectPacket(cx, cy, kx, ky, sig, amp, fresh) {
  const re = S.re, im = S.im;
  if (fresh) { for (let i = 0; i < GN; i++) { re[i] = 0; im[i] = 0; } }
  const gcx = cx * (GW - 1), gcy = cy * (GH - 1), inv = 1 / (2 * sig * sig);
  const rr = Math.ceil(sig * 3.2);
  for (let dy = -rr; dy <= rr; dy++) {
    const yy = Math.round(gcy) + dy; if (yy < 0 || yy >= GH) continue;
    for (let dx = -rr; dx <= rr; dx++) {
      const xx = Math.round(gcx) + dx; if (xx < 0 || xx >= GW) continue;
      const ox = xx - gcx, oy = yy - gcy, q = ox * ox + oy * oy;
      const g = amp * Math.exp(-q * inv);
      if (g < 1e-4) continue;
      const ph = kx * ox + ky * oy;
      const i = yy * GW + xx;
      re[i] += g * Math.cos(ph); im[i] += g * Math.sin(ph);
    }
  }
  // renormalise to a fixed total probability so brightness stays stable
  let tot = 0; for (let i = 0; i < GN; i++) tot += re[i]*re[i] + im[i]*im[i];
  const target = GN * 0.14;
  if (tot > 1e-9) { const sf = Math.sqrt(target / tot); for (let i = 0; i < GN; i++) { re[i] *= sf; im[i] *= sf; } }
}

// --- seed rebuild: fresh clean packet keyed on seed ---
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const a0 = fr(3) * TAU, km = 0.18 + P.momentum * 0.55;
  injectPacket(clp(P.x + (fr(1)-0.5)*0.2, 0.15, 0.85), clp(P.y + (fr(2)-0.5)*0.2, 0.15, 0.85),
               Math.cos(a0) * km, Math.sin(a0) * km, (0.09 + P.scale * 0.06) * Math.min(GW, GH), 1.0, true);
  S.lastSection = K.section; S.expo = 0.2;
}

// --- re-inject a new packet on section change (superposition -> interference) ---
if (S.lastSection == null) S.lastSection = K.section;
if (K.section !== S.lastSection) {
  const sIdx = ((K.section|0) % 8 + 8) % 8;
  const a1 = (sIdx * 0.9 + fr(sIdx + 20)) * TAU, km = 0.18 + P.momentum * 0.55 + A.bass * 0.25;
  injectPacket(0.30 + fr(sIdx + 7) * 0.4, 0.30 + fr(sIdx + 11) * 0.4,
               Math.cos(a1) * km, Math.sin(a1) * km, (0.08 + P.scale * 0.05) * Math.min(GW, GH), 0.9, false);
  S.lastSection = K.section;
}

// --- build the (slowly drifting) potential landscape: confining bowl + two scatterers ---
const ph1 = fr(5) * TAU, ph2 = fr(6) * TAU;
const drift = K.t * (0.05 + P.speed * 0.06);
const s1x = 0.5 + 0.26 * Math.cos(drift + ph1), s1y = 0.5 + 0.24 * Math.sin(drift * 1.2 + ph1);
const s2x = 0.5 + 0.28 * Math.cos(drift * 0.8 - ph2 + 2.1), s2y = 0.5 + 0.22 * Math.sin(drift * 0.9 + ph2 + 1.3);
const wK = P.well * 0.7, scH = P.scatter * 0.9;
const ssig = 0.11 * Math.min(GW, GH), sinv = 1 / (2 * ssig * ssig);
const bx = clp(P.x, 0.1, 0.9), by = clp(P.y, 0.1, 0.9);
if (!S.V || S.V.length !== GN) S.V = new Float32Array(GN);
{
  const V = S.V;
  for (let y = 0; y < GH; y++) {
    const fy = y / (GH - 1);
    for (let x = 0; x < GW; x++) {
      const fx = x / (GW - 1);
      const nx = (fx - bx) * 2, ny = (fy - by) * 2;
      let v = wK * (nx * nx + ny * ny);
      const d1x = (fx - s1x) * GW, d1y = (fy - s1y) * GH;
      v += scH * Math.exp(-(d1x*d1x + d1y*d1y) * sinv);
      const d2x = (fx - s2x) * GW, d2y = (fy - s2y) * GH;
      v += scH * 0.85 * Math.exp(-(d2x*d2x + d2y*d2y) * sinv);
      V[y * GW + x] = v;
    }
  }
}

// --- Visscher staggered leapfrog integration of i dpsi/dt = -0.5 lap psi + V psi ---
const re = S.re, im = S.im, V = S.V;
const dt = 0.15;
const substeps = clp(Math.round(1 + P.speed * 2.2), 1, 8);
for (let s = 0; s < substeps; s++) {
  // update real part from imaginary:  R += dt*(-0.5*lapI + V*I)
  for (let y = 0; y < GH; y++) {
    const yb = y * GW, up = y > 0 ? -GW : 0, dn = y < GH - 1 ? GW : 0;
    for (let x = 0; x < GW; x++) {
      const i = yb + x;
      const lf = x > 0 ? im[i-1] : 0, rt = x < GW-1 ? im[i+1] : 0;
      const lapI = lf + rt + im[i+up] + im[i+dn] - 4 * im[i];
      re[i] += dt * (-0.5 * lapI + V[i] * im[i]);
    }
  }
  // update imaginary part from (new) real:  I += dt*(0.5*lapR - V*R)
  for (let y = 0; y < GH; y++) {
    const yb = y * GW, up = y > 0 ? -GW : 0, dn = y < GH - 1 ? GW : 0;
    for (let x = 0; x < GW; x++) {
      const i = yb + x;
      const lf = x > 0 ? re[i-1] : 0, rt = x < GW-1 ? re[i+1] : 0;
      const lapR = lf + rt + re[i+up] + re[i+dn] - 4 * re[i];
      im[i] += dt * (0.5 * lapR - V[i] * re[i]);
    }
  }
}

// --- probability density + auto-exposure (smoothed peak) ---
const pb = S.pb; let curMax = 1e-6;
for (let i = 0; i < GN; i++) { const p = re[i]*re[i] + im[i]*im[i]; pb[i] = p; if (p > curMax) curMax = p; }
S.expo = S.expo + (curMax - S.expo) * 0.12;
const invExpo = 1 / (S.expo + 1e-6);

// --- palette helpers ---
function hsv(h, s, v) {
  h = ((h % 360) + 360) % 360; const c = v * s, xx = c * (1 - Math.abs((h / 60) % 2 - 1)), m = v - c;
  let r, g, b;
  if (h < 60) { r=c; g=xx; b=0; } else if (h < 120) { r=xx; g=c; b=0; }
  else if (h < 180) { r=0; g=c; b=xx; } else if (h < 240) { r=0; g=xx; b=c; }
  else if (h < 300) { r=xx; g=0; b=c; } else { r=c; g=0; b=xx; }
  return [r + m, g + m, b + m];
}
function iqp(t, off) {
  return [0.5 + 0.5 * Math.cos(TAU * (t + off)),
          0.5 + 0.5 * Math.cos(TAU * (t + off + 0.33)),
          0.5 + 0.5 * Math.cos(TAU * (t + off + 0.67))];
}

// --- render into coarse RGBA buffer, then upscale ---
const style = P.style;
const bri = (0.7 + P.energy * 0.95 + K.intensity * 0.32 + A.rms * 0.5);
const gamma = 0.66 - P.density * 0.30;
const bloom = P.density * 0.9 + A.treble * 0.3;
const amb = 0.2 + P.density * 0.06;
const hueBase = P.hue + K.section * 16 + K.t * 3 + A.mid * 40;
const sqExpo = Math.sqrt(S.expo) + 1e-6;

S.buf.loadPixels(); const px = S.buf.pixels;
for (let i = 0; i < GN; i++) {
  const p = pb[i], n = clp(p * invExpo, 0, 1.4);
  const amp = Math.pow(clp(n, 0, 1), gamma);            // tone-mapped amplitude 0..1
  const hot = clp(n - 0.6, 0, 0.8) * 1.25;              // white-hot core factor 0..1
  const ph = Math.atan2(im[i], re[i]);
  let r, g, b;
  if (style === 'thermal') {
    const m = clp(amp * bri, 0, 1.25);
    r = clp(0.18 + m * 1.7, 0, 1);                      // warm haze floor -> orange -> yellow
    g = clp(0.07 + m * 1.55 - 0.24, 0, 1);
    b = clp(0.13 + m * 2.3 - 1.3 + hot * 0.5, 0, 1);    // whitens at the hottest cores
  } else if (style === 'interference') {
    const env = 0.35 + Math.pow(n, 0.5);
    const tt = clp(re[i] / sqExpo, -1, 1);        // signed wavefront: crest -> white, trough -> deep blue
    const w = tt * 0.5 + 0.5;
    r = clp((0.12 + 0.82 * w) * env + 0.06, 0, 1);
    g = clp((0.22 + 0.78 * w) * env + 0.09, 0, 1);
    b = clp((0.55 + 0.45 * w) * (env + 0.15) + 0.16, 0, 1);
  } else if (style === 'spectral') {
    const c = iqp(ph / TAU + 0.5 + hueBase / 360, 0.0);
    const sh = clp(amp * bri + bloom * n * n * 0.5, 0, 1.3);
    r = clp(c[0] * sh + amb * 0.55 + hot * 0.4, 0, 1);
    g = clp(c[1] * sh + amb * 0.55 + hot * 0.4, 0, 1);
    b = clp(c[2] * sh + amb * 0.6 + hot * 0.4, 0, 1);
  } else if (style === 'mono') {
    const v = clp(amb + amp * (1 - amb) * bri + hot * 0.4, 0, 1);
    r = v; g = v; b = clp(v * 1.03, 0, 1);
  } else { // phase-density (default): hue = phase, value = |psi|^2, cores go white-hot
    const hh = (ph / TAU + 0.5) * 360 + hueBase;
    const v = clp(amb + amp * (1 - amb) * bri, 0, 1);
    const sat = clp(0.8 - amp * 0.5 - hot * 0.3, 0.15, 0.85);  // bright cores desaturate -> lift luma
    const c = hsv(hh, sat, v);
    const fl = (0.25 + bloom * 0.4) * Math.pow(clp(n, 0, 1.4) / 1.4, 1.4);   // white bloom on lumps
    r = clp(c[0] + fl, 0, 1); g = clp(c[1] + fl, 0, 1); b = clp(c[2] + fl, 0, 1);
  }
  const o = i << 2;
  px[o] = r * 255; px[o+1] = g * 255; px[o+2] = b * 255; px[o+3] = 255;
}
S.buf.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(S.buf, 0, 0, W, H);
pop();
